import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long computePower(long base, long exp) {
        long result = 1;
        for (long i = 0; i < exp; ++i) {
            result = (result * base) % MOD;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long P = sc.nextLong();
        long K = sc.nextLong();

        boolean[] visited = new boolean[(int) P];
        long[] count = new long[(int) P + 1];

        if (K == 0) {
            long product = 1;
            for (long i = 1; i < P; ++i) {
                product = (product * P) % MOD;
            }
            System.out.println(product);
            sc.close();
            return;
        }
        if (K == 1) {
            long product = 1;
            for (long i = 1; i <= P; ++i) {
                product = (product * P) % MOD;
            }
            System.out.println(product);
            sc.close();
            return;
        }

        for (long i = 0; i < P; ++i) {
            if (!visited[(int) i]) {
                long cycle_length = 0;
                long pos = i;
                while (!visited[(int) pos]) {
                    visited[(int) pos] = true;
                    cycle_length++;
                    pos = (K * pos) % P;
                }
                count[(int) cycle_length]++;
            }
        }

        long result = 1;
        for (long length = 2; length <= P; ++length) {
            if (count[(int) length] != 0) {
                long base = (count[(int) length] * length + 1) % MOD;
                long power = 1;
                for (long i = 0; i < count[(int) length]; ++i) {
                    power = (power * base) % MOD;
                }
                result = (result * power) % MOD;
            }
        }
        System.out.println(result);
        sc.close();
    }
}
